effect.shader:
void main() {
    vec2 uv = acScreenNorm;
    float c = (int(axis) == 0) ? uv.x : uv.y;
    float lado = step(split, c);
    vec2 other = uv;
    if (int(axis) == 0) other.x = (int(flip) == 1) ? (2.0 * split - uv.x) : uv.x;
    else                other.y = (int(flip) == 1) ? (2.0 * split - uv.y) : uv.y;

    float k = smoothstep(split - softness, split + softness, c);
    vec4 esq = texture(inputImg, other);
    vec4 dir = texture(inputImg, uv);
    fragColor = mix(esq, dir, k);
}
